import {tonicQuote,buyPPTonic} from './teamcraft-progress.js?v=0.90.30';
export function enduranceTonicMenu(a,back=()=>{}){const {state,openModal,document,$,rewardTransaction}=a,units=[...state.party,...state.reserve].filter(u=>u.hp>0&&!u.dead),safe=t=>String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 openModal('Endurance Tonic',`<p>Permanent +1 maximum PP to one individual move per dose. No small lifetime cap. Relearning, evolution and storage keep your investment; current PP is not refilled.</p><p>Choose a partner:</p>${units.map(u=>`<button data-pp-unit="${safe(u.uid)}">${safe(u.nickname||u.species.name)}</button>`).join('')}<button id="pp-back">Back</button>`);$('#pp-back').onclick=back;
 document.querySelectorAll('[data-pp-unit]').forEach(el=>el.onclick=()=>{const u=units.find(v=>v.uid===el.dataset.ppUnit);openModal('Choose a move',`${u.moves.map(m=>`<button data-pp-move="${m.id}">${safe(m.name)} · ${m.left}/${m.pp} PP · +${u.ppBonusByMoveId?.[m.id]||0} invested</button>`).join('')}<button id="pp-back">Back</button>`);$('#pp-back').onclick=()=>enduranceTonicMenu(a,back);document.querySelectorAll('[data-pp-move]').forEach(btn=>btn.onclick=()=>{const id=+btn.dataset.ppMove,m=u.moves.find(m=>m.id===id);openModal('Review PP investment',`<p>${safe(m.name)} · ${safe(u.nickname||u.species.name)}</p><label>Doses<input id="pp-count" type="number" min="1" max="10000" value="1"></label><p id="pp-quote" role="status"></p><button id="pp-confirm">Apply tonic</button><button id="pp-back">Cancel</button>`);const quote=()=>{const q=tonicQuote(state,u,id,+$('#pp-count').value);$('#pp-quote').textContent=`Cost ${q.cost.toLocaleString('en-GB')} doubloons · Maximum PP ${m.pp} → ${m.pp+(q.count||0)}. Each next dose costs 1,000 × total doses².`;$('#pp-confirm').disabled=!q.ok;};$('#pp-count').oninput=quote;quote();$('#pp-back').onclick=()=>enduranceTonicMenu(a,back);$('#pp-confirm').onclick=()=>{let ok=false;if(rewardTransaction(()=>{ok=buyPPTonic(state,u,id,+$('#pp-count').value);})&&ok){a.refresh?.();enduranceTonicMenu(a,back);}};});});
}
